def analytic_coefficients(k,N,L):
    if k == 0:
        return sp.zeros(0,0)
    if k == N:
        return sp.Matrix([[2,2*L/N],[2*L/N,0]])
    t=N-k
    return sp.Matrix([[0,-2,2*L/t,-2*L*k/(N*t)],[-2,-2,2*L/t,-2*L/t],[2*L/t,2*L/t,0,0],[-2*L*k/(N*t),-2*L/t,0,0]])

